INSERT INTO `faqs` (`id`, `question`, `answer`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(18, 'Why partner with Cloud Aspire?', 'We treat your business as our own. By pairing data-driven analytics with creative excellence, we design campaigns that deliver measurable bottom-line growth, not vanity metrics.', 'active', 1, '2026-08-28 20:23:45', '2026-08-28 20:23:45'),
(19, 'How do you approach multi-channel digital growth?', 'We begin with a deep market audit, identify high-intent conversion bottlenecks, and deploy a synchronized mix of SEO, Meta/Google Ads, content, and high-speed landing pages.', 'active', 2, '2026-08-28 20:23:45', '2026-08-28 20:23:45'),
(20, 'How quickly can we expect to see tangible results?', 'Paid performance campaigns generate qualified inquiries within days of launch. SEO ranking momentum typically builds strong compounding returns within 60 to 90 days.', 'active', 3, '2026-08-28 20:23:45', '2026-08-28 20:23:45'),
(21, 'Do you offer custom tailored packages?', 'Yes! We craft bespoke growth roadmaps aligned with your immediate goals, target CAC (Customer Acquisition Cost), and market trajectory.', 'active', 4, '2026-08-28 20:23:45', '2026-08-28 20:23:45'),
(22, 'How do you report on campaign performance?', 'You receive 24/7 access to live analytics dashboards and concise executive summaries detailing spend, leads, conversions, and ROI.', 'active', 5, '2026-08-28 20:23:45', '2026-08-28 20:23:45');
