INSERT INTO `mail_queue` (`id`, `recipient`, `subject`, `body`, `alt_body`, `is_html`, `status`, `attempts`, `max_attempts`, `error_message`, `created_at`, `processed_at`) VALUES
(144, 'lead@example.com', 'Thank You for Contacting Cloud Aspire', '\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Thank You for Reaching Out</title>\r\n</head>\r\n<body style=\"margin: 0; padding: 0; background-color: #0f172a; font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; color: #334155;\">\r\n    <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color: #0f172a; padding: 32px 16px;\">\r\n        <tr>\r\n            <td align=\"center\">\r\n                <!-- Email Container -->\r\n                <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"max-width: 600px; width: 100%; margin: 0 auto;\">\r\n                    <!-- Brand Header -->\r\n                    <tr>\r\n                        <td align=\"center\" style=\"padding-bottom: 24px;\">\r\n                            <a href=\"https://cloudaspire.in\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\r\n                                <img src=\"https://cloudaspire.in/uploads/site_logo_1783239874.png\" alt=\"Cloud Aspire\" style=\"max-height: 48px; max-width: 200px; height: auto; width: auto; object-fit: contain; vertical-align: middle; display: inline-block; margin-bottom: 8px;\">\r\n                            </a>\r\n                        </td>\r\n                    </tr>\r\n                    \r\n                    <!-- Main Card -->\r\n                    <tr>\r\n                        <td>\r\n                            <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.2); border: 1px solid rgba(255, 255, 255, 0.1);\">\r\n                                <!-- Card Header Banner -->\r\n                                <tr>\r\n                                    <td style=\"background: linear-gradient(135deg, #1e1b4b 0%, #312e81 50%, #4338ca 100%); padding: 32px 28px; text-align: center;\">\r\n                                        <div style=\"display: inline-block; padding: 5px 14px; background: #10b981; color: #ffffff; border-radius: 20px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 12px;\">INQUIRY RECEIVED</div>\r\n                                        <h1 style=\"color: #ffffff; margin: 0; font-size: 22px; font-weight: 700; line-height: 1.3;\">Thank You for Reaching Out</h1>\r\n                                        <p style=\"color: #cbd5e1; margin: 8px 0 0 0; font-size: 14px; line-height: 1.5;\">We have received your message and are on it!</p>\r\n                                    </td>\r\n                                </tr>\r\n\r\n                                <!-- Card Body -->\r\n                                <tr>\r\n                                    <td style=\"padding: 32px 28px; font-size: 15px; line-height: 1.6; color: #334155;\">\r\n                                        \r\n    <div style=\"text-align: left;\">\r\n        <h2 style=\"color: #0f172a; margin-top: 0; font-size: 20px; font-weight: 700;\">Hello, Interested Lead!</h2>\r\n        <p style=\"color: #334155; line-height: 1.6; font-size: 15px;\">\r\n            Thank you for reaching out to us. We have successfully received your inquiry regarding <strong>Web Development</strong>.\r\n        </p>\r\n        \r\n        <div style=\"background: linear-gradient(135deg, #f0fdf4 0%, #e0f2fe 100%); border: 1px solid #bbf7d0; border-radius: 12px; padding: 20px; margin: 24px 0;\">\r\n            <p style=\"margin: 0 0 8px 0; color: #166534; font-weight: 700; font-size: 15px;\">What happens next?</p>\r\n            <ul style=\"margin: 0; padding-left: 20px; color: #1e293b; font-size: 14px; line-height: 1.6;\">\r\n                <li>Our specialist team will review your requirements.</li>\r\n                <li>We will prepare tailored solutions and answers for you.</li>\r\n                <li>A representative will get in touch with you within <strong>24 hours</strong>.</li>\r\n            </ul>\r\n        </div>\r\n\r\n        <p style=\"color: #64748b; font-size: 14px; margin-bottom: 24px;\">\r\n            If your request is urgent, you can reply directly to this email or reach us through our official portal.\r\n        </p>\r\n\r\n        <div style=\"border-top: 1px solid #e2e8f0; padding-top: 16px;\">\r\n            <p style=\"margin: 0; color: #334155; font-size: 14px;\">Warm regards,</p>\r\n            <p style=\"margin: 4px 0 0 0; color: #0f172a; font-weight: 700; font-size: 15px;\">The Cloud Aspire Team</p>\r\n        </div>\r\n    </div>\r\n                                        \r\n        <div style=\"text-align: center; margin: 30px 0 10px 0;\">\r\n            <a href=\"https://cloudaspire.in\" target=\"_blank\" style=\"background: linear-gradient(135deg, #4f46e5 0%, #3b82f6 100%); color: #ffffff; padding: 13px 32px; text-decoration: none; border-radius: 8px; font-weight: 600; font-size: 14px; display: inline-block; letter-spacing: 0.2px; box-shadow: 0 4px 12px rgba(79, 70, 229, 0.25);\">Visit Our Website &rarr;</a>\r\n        </div>\r\n                                    </td>\r\n                                </tr>\r\n                            </table>\r\n                        </td>\r\n                    </tr>\r\n\r\n                    <!-- Footer -->\r\n                    <tr>\r\n                        <td style=\"padding: 28px 16px 12px 16px; text-align: center; color: #94a3b8; font-size: 12px; line-height: 1.6;\">\r\n                            \r\n                            <p style=\"margin: 0 0 8px 0; color: #cbd5e1; font-weight: 500;\">&copy; 2026 Cloud Aspire. All rights reserved.</p>\r\n                            <p style=\"margin: 0;\">\r\n                                <a href=\"https://cloudaspire.in\" target=\"_blank\" style=\"color: #818cf8; text-decoration: none; margin: 0 8px;\">Website</a> &bull;\r\n                                <a href=\"mailto:cloudaspire2025@gmail.com\" style=\"color: #818cf8; text-decoration: none; margin: 0 8px;\">Support</a>\r\n                            </p>\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</body>\r\n</html>', '\r\n\r\n\r\n\r\n    \r\n    \r\n    Thank You for Reaching Out\r\n\r\n\r\n    \r\n        \r\n            \r\n                \r\n                \r\n                    \r\n                    \r\n                        \r\n                            \r\n                                \r\n                            \r\n                        \r\n                    \r\n                    \r\n                    \r\n                    \r\n                        \r\n                            \r\n                                \r\n                                \r\n                                    \r\n                                        INQUIRY RECEIVED\r\n                                        Thank You for Reaching Out\r\n                                        We have received your message and are on it!\r\n                                    \r\n                                \r\n\r\n                                \r\n                                \r\n                                    \r\n                                        \r\n    \r\n        Hello, Interested Lead!\r\n        \r\n            Thank you for reaching out to us. We have successfully received your inquiry regarding Web Development.\r\n        \r\n        \r\n        \r\n            What happens next?\r\n            \r\n                Our specialist team will review your requirements.\r\n                We will prepare tailored solutions and answers for you.\r\n                A representative will get in touch with you within 24 hours.\r\n            \r\n        \r\n\r\n        \r\n            If your request is urgent, you can reply directly to this email or reach us through our official portal.\r\n        \r\n\r\n        \r\n            Warm regards,\r\n            The Cloud Aspire Team\r\n        \r\n    \r\n                                        \r\n        \r\n            Visit Our Website &rarr;\r\n        \r\n                                    \r\n                                \r\n                            \r\n                        \r\n                    \r\n\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            &copy; 2026 Cloud Aspire. All rights reserved.\r\n                            \r\n                                Website &bull;\r\n                                Support\r\n                            \r\n                        \r\n                    \r\n                \r\n            \r\n        \r\n    \r\n\r\n', 1, 'failed', 3, 3, 'SMTP Error: Could not connect to SMTP host. Failed to connect to server | SMTP Error: Could not connect to SMTP host. Failed to connect to server SMTP server error: Failed to connect to server Additional SMTP info: php_network_getaddresses: getaddrinfo for portel.cloudaspire.in failed: Name or service not known', '2026-08-29 07:12:38', '2026-10-12 11:11:35'),
