INSERT INTO `reviews` (`id`, `name`, `email`, `star_rating`, `message`, `rating`, `review_text`, `designation`, `company`, `status`, `created_at`, `updated_at`) VALUES
(13, 'PREM KUMAR', 'tamilaninstamedia1@gmail.com', 5, 'I recently contacted Cloudaspire for website development and Meta Ads for my online store, HP Gift Shop. I was looking for a reliable team that could provide good-quality work at an affordable price, and Cloudaspire did a great job.\r\n\r\nThey understood my requirements clearly and delivered a professional website along with a well-planned Meta Ads setup. The team was responsive, supportive, and made the process easy from start to finish.\r\n\r\nI really appreciate the affordable pricing, quality of work, and professional support provided by the Cloudaspire team.\r\n\r\nHighly recommended for anyone looking for affordable website development and digital marketing services! ', '5', 'I recently contacted Cloudaspire for website development and Meta Ads for my online store, HP Gift Shop. I was looking for a reliable team that could provide good-quality work at an affordable price, and Cloudaspire did a great job.\r\n\r\nThey understood my requirements clearly and delivered a professional website along with a well-planned Meta Ads setup. The team was responsive, supportive, and made the process easy from start to finish.\r\n\r\nI really appreciate the affordable pricing, quality of work, and professional support provided by the Cloudaspire team.\r\n\r\nHighly recommended for anyone looking for affordable website development and digital marketing services! ', NULL, 'Hp Gift Shop', 'approved', '2026-09-25 03:47:32', '2026-09-25 03:47:58'),
(14, 'Shanmuga Priya G', 'priya30shanmuga@gmail.com', 5, 'Had a great experience with Cloud Aspire! Their digital marketing team is professional, creative, and understands business requirements very well. Their approach towards SEO, Google Ads, and social media marketing is really good. Highly recommended for businesses looking to improve their online presence.', '5', 'Had a great experience with Cloud Aspire! Their digital marketing team is professional, creative, and understands business requirements very well. Their approach towards SEO, Google Ads, and social media marketing is really good. Highly recommended for businesses looking to improve their online presence.', NULL, 'Riya Beauty Studio', 'approved', '2026-09-25 03:51:20', '2026-09-25 03:57:14');
