INSERT INTO `services` (`id`, `service_name`, `slug`, `short_description`, `full_description`, `icon`, `image`, `price`, `status`, `created_at`, `updated_at`) VALUES
(1, 'SEO,AEO&GEO Optimization', 'seo-optimization', 'Dominate search rankings, drive targeted organic traffic, and outrank competitors with proven data-driven SEO strategies.', 'Comprehensive SEO including technical site audits, on-page optimization, high-authority backlink outreach, keyword research, and rank tracking.', 'fa-search', 'uploads/services/service_1789994678_6ab126b6c2b6e.png', '₹4,999/mo', 'active', '2026-08-29 07:12:35', '2026-09-21 12:45:06'),
(2, 'Google & Meta Ads', 'google-meta-ads', 'Maximize ROI with high-converting paid ad campaigns across Google Search, Display, YouTube, Instagram, and Facebook.', 'Targeted PPC advertising, dynamic retargeting, conversion rate optimization, lower cost-per-acquisition, and transparent analytics.', 'fa-bullhorn', 'uploads/services/service_1789721271_7abfa3.png', '₹7,999/mo', 'active', '2026-08-29 07:12:35', '2026-09-18 08:48:24'),
(3, 'Social Media Marketing', 'social-media-marketing', 'Build brand authority, engage your audience, and scale follower growth across Instagram, LinkedIn, and Facebook.', 'Creative content creation, Reels/Shorts production, active community management, influencer partnerships, and growth campaigns.', 'fa-mobile-alt', 'uploads/services/service_1789994488_6ab125f867ede.png', '', 'active', '2026-08-29 07:12:35', '2026-09-21 12:41:29'),
(4, 'Website & App Development', 'website-app-development', 'Ultra-fast, mobile-responsive custom websites and web applications built to turn visitors into paying customers.', 'Custom PHP/JavaScript/HTML5 web development, e-commerce portals, web applications, landing pages, and cloud hosting setup.', 'fa-code', 'uploads/services/service_1789994893_6ab1278dc3ecd.png', '₹9,999', 'active', '2026-08-29 07:12:35', '2026-09-21 12:48:14'),
(5, 'Brand Identity & Design', 'brand-identity-design', 'Establish a memorable brand identity with professional logos, graphic design, and cohesive visual branding.', 'Comprehensive branding kits: logo packages, typography, color palettes, vector assets, stationery, and digital UI/UX assets.', 'fa-paint-brush', 'uploads/services/service_1789995162_6ab1289adf467.png', '₹3,999', 'active', '2026-08-29 07:12:35', '2026-09-21 12:52:43'),
(6, 'Content Marketing & Copywriting', 'content-marketing', 'Compelling storytelling and conversion copywriting that captivates your audience and drives organic engagement.', 'SEO-optimized blog writing, landing page copywriting, email newsletters, whitepapers, and high-converting sales funnels.', 'fa-pen-fancy', 'uploads/services/service_1789995289_6ab12919c3938.png', '₹3,499/mo', 'active', '2026-08-29 07:12:35', '2026-09-21 12:54:50');
