INSERT INTO `testimonials` (`id`, `name`, `designation`, `message`, `image`, `status`, `created_at`, `updated_at`) VALUES
(4, 'PREM KUMAR', 'CEO', '“Cloud Aspire delivered an excellent website with a clean design and smooth user experience. Their team was professional, responsive, and understood our requirements perfectly.”', 'uploads/testimonials/testimonial_1789708740_6aacc9c4a6ffd.jpeg', 'active', '2026-09-18 05:19:00', '2026-09-18 05:19:00'),
(5, 'P. KARTHICKRAJA B.E', 'Co-Founder', '“At Cloud Aspire, we believe in turning ideas into impactful digital solutions. Our team’s passion, creativity, and dedication drive us to deliver better results for every client.”', 'uploads/testimonials/testimonial_1789709130_6aaccb4a3cf4e.jpeg', 'active', '2026-09-18 05:25:30', '2026-09-18 05:25:30'),
(6, 'ABIRAMI R', 'junior SEO Executive', '“Cloud Aspire has given me a great opportunity to develop my SEO skills through real-world projects. I’ve learned a lot about SEO strategies, optimization, and performance analysis while working with a supportive team.”', 'uploads/testimonials/testimonial_1789709262_6aaccbceca8b0.jpeg', 'active', '2026-09-18 05:27:42', '2026-09-18 05:27:42'),
(7, 'JEYACHANDRA M', 'junior SEO Executive', '“Cloud Aspire has been a great place to learn and grow in SEO. Working on practical projects helped me understand SEO beyond theory and improve my confidence as a Junior SEO Executive.”', 'uploads/testimonials/testimonial_1789709364_6aaccc34d9e9c.jpeg', 'active', '2026-09-18 05:29:24', '2026-09-18 05:29:24'),
(8, 'SHANMUGA PRIYA', 'senior developer', '“Cloud Aspire provides a great environment to work on challenging projects and explore modern technologies. The collaborative team culture and focus on quality make every project a valuable learning experience.”\r\n\r\n— Senior Developer', 'uploads/testimonials/testimonial_1789709738_6aaccdaaae195.jpeg', 'active', '2026-09-18 05:33:28', '2026-09-18 05:35:38'),
(9, 'KAVITHA A', 'Assistent senior developer', '“Cloud Aspire has given me the opportunity to strengthen my development skills through practical projects and teamwork. Every project brings new challenges, learning opportunities, and professional growth.”\r\n\r\n— Assistant Senior Developer', 'uploads/testimonials/testimonial_1789709997_6aaccead203af.jpeg', 'active', '2026-09-18 05:39:57', '2026-09-18 05:39:57');
