INSERT INTO `why_choose_us` (`id`, `question`, `answer`, `icon`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(16, 'Proven Track Record', '500+ successful digital initiatives with measurable ROI across e-commerce, healthcare, and SaaS.', 'fa-trophy', 'active', 1, '2026-08-28 20:07:35', '2026-08-28 20:07:35'),
(17, 'Certified Specialists', 'Dedicated specialists in performance marketing, technical SEO, and conversion-focused web development.', 'fa-users-gear', 'active', 2, '2026-08-28 20:07:35', '2026-08-28 20:07:35'),
(18, 'Data-Driven Growth', 'Every campaign decision is backed by live analytics and deep audience behavior modeling.', 'fa-chart-line', 'active', 3, '2026-08-28 20:07:35', '2026-08-28 20:07:35'),
(19, 'Dedicated Support', 'Direct access to account leads and transparent bi-weekly strategy alignment calls.', 'fa-headset', 'active', 4, '2026-08-28 20:07:35', '2026-08-28 20:07:35'),
(20, 'Rapid Execution', 'Fast turnaround without sacrificing code quality, security, or creative finesse.', 'fa-bolt', 'active', 5, '2026-08-28 20:07:35', '2026-08-28 20:07:35'),
(21, 'Transparent Analytics', 'Live real-time performance dashboards so you always know your exact cost per acquisition.', 'fa-shield-halved', 'active', 6, '2026-08-28 20:07:35', '2026-08-28 20:07:35');
